async function evaluateInfrastructure() {
  const metrics = await prometheus.query('rate(db_iops_total[5m])');
  const currentIops = metrics.data.result[0].value[1];

  if (currentIops > 8000) {
    const trend = await analyzeTrend(metrics);
    if (trend.predictedFailureInMinutes < 60) {
      const proposal = await llm.draftScalingProposal({
        currentIops,
        architecture: 'PostgreSQL',
        goal: 'Prevent IOPS saturation'
      });
      await github.createPullRequest(proposal.terraformCode);
    }
  }
}
